INSERT INTO pages_seo (page_key, title, description, h1, og_title, og_description, robots) VALUES
('home', 'IT-решения для бизнеса — BizDevOps', 'Сайты, VPS, DevOps, безопасность и поддержка под ключ. Прямая работа, смета до старта, ответ за 1–2 часа.', 'IT-решения для бизнеса без лишней бюрократии', 'IT-решения для бизнеса — BizDevOps', 'Разработка, администрирование и сопровождение — один ответственный специалист.', 'index,follow'),
('privacy', 'Политика конфиденциальности — BizDevOps', 'Политика обработки персональных данных сайта BizDevOps.', 'Политика конфиденциальности', 'Политика конфиденциальности', 'Как обрабатываются персональные данные с формы заявки.', 'index,follow'),
('offer', 'Публичная оферта — BizDevOps', 'Публичная оферта на оказание IT-услуг BizDevOps.', 'Публичная оферта', 'Публичная оферта', 'Условия оказания IT-услуг и подачи заявок.', 'index,follow')
INSERT INTO services (slug, title, short_text, full_text, price_from, price_note, period, icon, sort_order, is_active, is_featured, cta_label) VALUES
('site-support', 'Сопровождение сайтов', 'WordPress, Bitrix и кастомные PHP-сайты: обновления, фиксы, скорость, бэкапы.', 'Регулярные обновления CMS/плагинов, исправление ошибок, мониторинг доступности, резервные копии и мелкие доработки.', 15000.00, 'в месяц', 'monthly', 'support', 10, 1, 1, 'Заказать сопровождение'),
('landing-dev', 'Разработка лендингов и веб-сервисов', 'Чистый PHP 8.2 + MySQL: лендинги, кабинеты, формы, интеграции без тяжёлых фреймворков.', 'Проектирование, вёрстка, бэкенд, админка, SEO-база и деплой на ваш VPS.', 45000.00, 'от проекта', 'one_time', 'code', 20, 1, 1, 'Обсудить проект'),
('linux-admin', 'Администрирование Linux / VPS', 'Apache, Nginx, PHP-FPM, MySQL, права, пользователи, автозапуск и hardening.', 'Настройка серверов с нуля, перенос проектов, оптимизация и порядок в инфраструктуре.', 8000.00, 'разово / час', 'custom', 'server', 30, 1, 0, 'Заказать админку'),
('migrations-backups', 'Миграции, бэкапы, мониторинг', 'Перенос сайтов без простоя, скрипты бэкапов, алерты в Telegram.', 'Миграции между хостингами/VPS, проверка целостности, мониторинг uptime и диска.', 12000.00, 'от задачи', 'one_time', 'backup', 40, 1, 0, 'Заказать'),
('ssl-security', 'SSL, безопасность, hardening', 'HTTPS, файрвол, права, защита админок, аудит уязвимостей типовых CMS.', 'Let''s Encrypt, fail2ban, ограничение доступа, рекомендации по безопасности.', 10000.00, 'от аудита', 'one_time', 'shield', 50, 1, 1, 'Заказать аудит'),
('crm-integrations', 'Интеграции CRM / платежи / API', 'Связка сайта с CRM, платёжками, вебхуками и внутренними системами.', 'Проектирование обмена данными, обработка ошибок, логирование и документация.', 25000.00, 'от интеграции', 'one_time', 'api', 60, 1, 0, 'Заказать интеграцию'),
('telegram-bots', 'Telegram-боты и уведомления', 'Боты для заявок, алертов, статусов заказов и внутренних процессов.', 'От простого notify-бота до сценариев с кнопками, очередями и БД.', 18000.00, 'от бота', 'one_time', 'bot', 70, 1, 0, 'Заказать бота'),
('seo-audit', 'SEO-аудит и техническое SEO', 'Индексация, скорость, разметка, sitemap, robots, мета, Core Web Vitals.', 'Технический аудит + список правок с приоритетами и оценкой эффекта.', 15000.00, 'аудит', 'one_time', 'seo', 80, 1, 0, 'Заказать аудит'),
('automation', 'Автоматизация рутины', 'Скрипты, cron, отчёты, синхронизации — меньше ручной работы.', 'Автоматизация типовых операций админа и бизнеса на PHP/bash.', 12000.00, 'от задачи', 'custom', 'gear', 90, 1, 0, 'Заказать'),
('consulting', 'Разовые консультации и аудит инфраструктуры', 'Разбор текущего стека, рисков, узких мест и плана улучшений.', 'Созвон/аудит с письменными рекомендациями и сметой на внедрение.', 5000.00, 'за сессию', 'one_time', 'chat', 100, 1, 0, 'Записаться'),
('subscription-support', 'Абонентская IT-поддержка', 'Фиксированный пакет часов: инциденты, мелкие доработки, советы.', 'Ежемесячная поддержка с приоритетом реакции и понятным объёмом работ.', 30000.00, 'в месяц', 'monthly', 'handshake', 110, 1, 1, 'Подключить абонентку'),
('wordpress-bitrix', 'WordPress / Bitrix под ключ', 'Сборка, доработки, безопасность и ускорение популярных CMS.', 'От установки до продакшн-hardening и базового SEO.', 35000.00, 'от проекта', 'one_time', 'cms', 15, 1, 0, 'Заказать');
